s($,"dpe","bxi",()=>new A.a5x(A.eJ(2002),"Russia","russia_plate","Letters, digits and a region code with RUS and the flag. Only the twelve Cyrillic capitals that look Latin are used. Mission code 127 is refused (COUNTRY NOT FOUND)."))
s($,"do7","c7l",()=>new A.Ut("Belarus","russia_plate",'Flag and BY on white, Latin letters that read the same in Cyrillic, a region digit after the dash. Diplomatic mission code 09 is refused in every layer with "COUNTRY NOT FOUND".'))
s($,"doG","c7I",()=>new A.Zl("Gibraltar","spain_plate","G, a serial and a series letter. Not drawn: the pre-Brexit EU star ring, the square rear plate, the pre-2001 serials without a series letter beyond `G 1`, and the Governor's and military vehicles."))
s($,"doh","c7s",()=>new A.VG("Ceuta","spain_plate",'Spain\'s national series as issued in Ceuta. Diplomatic embassy code 83 is refused in every layer with "COUNTRY NOT FOUND".'))
